def pickLocale(loc: Any) -> Any:
    return loc if (js.truthy(loc) and js.truthy(own(LABELS, loc))) else "en"


def label(loc: Any, key: Any) -> Any:
    m: Any = js.nullish(
        (_v1 if js.defined(_v1 := js.get(LABELS, pickLocale(loc))) else js.get(LABELS, "en")), {}
    )
    en: Any = js.nullish(js.get(LABELS, "en"), {})
    return js.nullish((_v2 if js.defined(_v2 := own(m, key)) else own(en, key)), "")


def badgeClass(d: Any) -> Any:
    if not js.truthy(js.get(d, "HasDosha")):
        return "none"
    if js.truthy(js.get(d, "Cancelled")):
        return "cancelled"
    if js.get(d, "Status") == "purn":
        return "purn"
    return "mild"


def statusBadgeText(loc: Any, d: Any) -> Any:
    l: Any = pickLocale(loc)
    south: Any = js.get(SOUTH_PROSE, l)
    if js.truthy(south):
        if not js.truthy(js.get(d, "HasDosha")):
            return js.get(js.get(south, "badge"), "none")
        if js.truthy(js.get(d, "Cancelled")):
            return js.get(js.get(south, "badge"), "cancelled")
        return (
            js.get(js.get(south, "badge"), "purn")
            if (js.get(d, "Status") == "purn")
            else js.get(js.get(south, "badge"), "mild")
        )
    if not js.truthy(js.get(d, "HasDosha")):
        if l == "hi":
            return "मंगल दोष नहीं"
        if l == "mr":
            return "मंगळ दोष नाही"
        return "No Mangal Dosha"
    if js.truthy(js.get(d, "Cancelled")):
        if l == "hi":
            return "मंगल दोष — परिहार सहित"
        if l == "mr":
            return "मंगळ दोष — परिहार सहित"
        return "Mangal Dosha (with cancellation)"
    if js.get(d, "Status") == "purn":
        if l == "hi":
            return "पूर्ण मंगल दोष"
        if l == "mr":
            return "पूर्ण मंगळ दोष"
        return "Full Mangal Dosha"
    if l == "hi":
        return "अल्प मंगल दोष"
    if l == "mr":
        return "अल्प मंगळ दोष"
    return "Mild Mangal Dosha"


def severityLabel(loc: Any, status: Any) -> Any:
    l: Any = pickLocale(loc)
    south: Any = js.get(SOUTH_PROSE, l)
    if js.truthy(south):
        return (
            js.get(js.get(south, "severity"), "purn")
            if (status == "purn")
            else (
                js.get(js.get(south, "severity"), "mild")
                if (status == "mild")
                else js.get(js.get(south, "severity"), "none")
            )
        )
    if l == "hi":
        return "पूर्ण" if (status == "purn") else ("अल्प" if (status == "mild") else "कोई नहीं")
    if l == "mr":
        return "पूर्ण" if (status == "purn") else ("अल्प" if (status == "mild") else "कोणताही नाही")
    return "full" if (status == "purn") else ("mild" if (status == "mild") else "no")


def formatGenerated(iso: Any = js.UNDEF) -> Any:
    if not js.truthy(iso):
        return ""
    d: Any = parseTimestamp(iso)
    if js.is_nan(d.get_time()):
        return iso

    def p(n: Any) -> Any:
        return js.pad_start(js.s(n), 2, "0")

    return (
        js.s(d.utc_year())
        + "-"
        + js.s(p(js.add(d.utc_month(), 1)))
        + "-"
        + js.s(p(d.utc_date()))
        + " "
        + js.s(p(d.utc_hours()))
        + ":"
        + js.s(p(d.utc_minutes()))
        + " UTC"
    )


def diagnosisText(loc: Any, d: Any) -> Any:
    l: Any = pickLocale(loc)
    south: Any = js.get(SOUTH_PROSE, l)
    if js.truthy(south):
        if not js.truthy(js.get(d, "HasDosha")):
            return js.get(south, "diagnosisNone")
        return js.get(south, "diagnosis")(
            js.nullish(js.get_optional(js.get(d, "MarsPlacement"), "sign"), ""),
            formatHouses(loc, js.get(d, "HousesOccupied")),
            severityLabel(loc, js.get(d, "Status")),
        )
    if not js.truthy(js.get(d, "HasDosha")):
        if l == "hi":
            return "मंगल का स्थान दोषकारक भावों (1, 4, 7, 8, 12) में नहीं है, अतः मंगल दोष नहीं है।"
        if l == "mr":
            return "मंगळाचे स्थान दोषकारक स्थानांमध्ये (1, 4, 7, 8, 12) नाही, त्यामुळे मंगळ दोष नाही."
        return "Mars does not occupy any of the affected houses (1, 4, 7, 8, 12), so no Mangal Dosha is present."
    sign: Any = js.nullish(js.get_optional(js.get(d, "MarsPlacement"), "sign"), "")
    houses: Any = formatHouses(loc, js.get(d, "HousesOccupied"))
    sev: Any = severityLabel(loc, js.get(d, "Status"))
    if l == "hi":
        return (
            "मंगल "
            + js.s(sign)
            + " राशि में स्थित है तथा "
            + js.s(houses)
            + " भाव में है — यह मंगल दोष का "
            + js.s(sev)
            + " रूप है।"
        )
    if l == "mr":
        return (
            "मंगळ "
            + js.s(sign)
            + " राशीत आहे आणि "
            + js.s(houses)
            + " स्थानात आहे — हा मंगळ दोषाचा "
            + js.s(sev)
            + " प्रकार आहे."
        )
    return (
        "Mars sits in "
        + js.s(sign)
        + ", in house "
        + js.s(houses)
        + " — this constitutes a "
        + js.s(sev)
        + " form of Mangal Dosha."
    )


def formatHouses(loc: Any, houses: Any = js.UNDEF) -> Any:
    l: Any = pickLocale(loc)
    hs: Any = houses if js.is_array(houses) else []
    lagna: Any = js.map_(js.filter_(hs, (lambda h: js.gt(h, 0))), js.s)
    moon: Any = js.map_(js.filter_(hs, (lambda h: js.lt(h, 0))), (lambda h: js.s(js.neg(h))))
    parts: Any = []
    south: Any = js.get(SOUTH_PROSE, l)
    if js.truthy(south):
        if js.truthy(js.length(lagna)):
            parts.append(js.get(south, "fromLagna")(js.join(lagna, ", ")))
        if js.truthy(js.length(moon)):
            parts.append(js.get(south, "fromMoon")(js.join(moon, ", ")))
    elif l == "hi":
        if js.truthy(js.length(lagna)):
            parts.append(("लग्न से " + js.join(lagna, ", ")))
        if js.truthy(js.length(moon)):
            parts.append(("चंद्र से " + js.join(moon, ", ")))
    elif l == "mr":
        if js.truthy(js.length(lagna)):
            parts.append(("लग्नापासून " + js.join(lagna, ", ")))
        if js.truthy(js.length(moon)):
            parts.append(("चंद्रापासून " + js.join(moon, ", ")))
    else:
        if js.truthy(js.length(lagna)):
            parts.append((js.join(lagna, ", ") + " from the lagna"))
        if js.truthy(js.length(moon)):
            parts.append((js.join(moon, ", ") + " from the Moon"))
    return js.join(parts, "; ")


def marriageImplicationsText(loc: Any, d: Any) -> Any:
    l: Any = pickLocale(loc)
    south: Any = js.get(SOUTH_PROSE, l)
    if js.truthy(south):
        if not js.truthy(js.get(d, "HasDosha")):
            return js.get(js.get(south, "marriage"), "none")
        if js.truthy(js.get(d, "Cancelled")):
            return js.get(js.get(south, "marriage"), "cancelled")
        return (
            js.get(js.get(south, "marriage"), "purn")
            if (js.get(d, "Status") == "purn")
            else js.get(js.get(south, "marriage"), "mild")
        )
    if not js.truthy(js.get(d, "HasDosha")):
        if l == "hi":
            return "विवाह के दृष्टिकोण से मंगल दोष से सम्बंधित कोई बाधा नहीं है। मेल मिलान सामान्य रूप से किया जा सकता है।"
        if l == "mr":
            return "विवाहाच्या दृष्टीने मंगळ दोषाशी संबंधित कोणताही अडथळा नाही. मेळ जुळवणी सामान्यपणे केली जाऊ शकते."
        return "From a marriage standpoint, there is no Mangal Dosha-related obstacle. Match making can proceed normally."
    if js.truthy(js.get(d, "Cancelled")):
        if l == "hi":
            return "यद्यपि मंगल दोष उपस्थित है, परन्तु शास्त्रीय परिहार लागू होने से इसका प्रभाव क्षीण हो जाता है। मेल मिलान में सामान्यतः इसे महत्वपूर्ण बाधा नहीं माना जाता।"
        if l == "mr":
            return "जरी मंगळ दोष उपस्थित आहे, तरी शास्त्रीय परिहार लागू असल्याने त्याचा प्रभाव कमी होतो. मेळ जुळवणीत साधारणपणे हा महत्त्वाचा अडथळा मानला जात नाही."
        return "Although Mangal Dosha is present, classical cancellation rules apply and substantially reduce its effect. Match making typically does not treat this as a significant obstacle."
    if js.get(d, "Status") == "purn":
        if l == "hi":
            return "पूर्ण मंगल दोष विवाह सम्बन्धों में चुनौतियाँ ला सकता है। पारंपरिक रूप से अनुशंसित है कि साथी की कुंडली में भी मंगल दोष हो (या समान भारता हो), जिससे प्रभाव संतुलित हो जाए। दोनों कुंडलियों की सावधानीपूर्वक जाँच एवं उचित मेल मिलान महत्वपूर्ण है।"
        if l == "mr":
            return "पूर्ण मंगळ दोष विवाह संबंधांत आव्हाने आणू शकतो. पारंपरिकपणे शिफारस केली जाते की जोडीदाराच्या कुंडलीतही मंगळ दोष असावा (किंवा समान तीव्रता), ज्यामुळे परिणाम संतुलित होतो. दोन्ही कुंडल्यांची काळजीपूर्वक तपासणी आणि योग्य मेळ जुळवणी महत्त्वाची आहे."
        return "Full Mangal Dosha can introduce challenges in marriage relationships. Tradition recommends that the partner's chart also carry Mangal Dosha (or comparable intensity) so the effect is balanced between the two. A careful study of both charts and proper match making are important."
    if l == "hi":
        return "अल्प मंगल दोष का प्रभाव सीमित होता है, परन्तु मेल मिलान करते समय इसे ध्यान में रखना उचित है। साथी की कुंडली को भी इसके साथ मिलाकर जाँच लीजिए।"
    if l == "mr":
        return "अल्प मंगळ दोषाचा प्रभाव मर्यादित असतो, परंतु मेळ जुळवणी करताना याचा विचार करणे योग्य आहे. जोडीदाराची कुंडलीही याच्यासोबत तपासून घ्या."
    return "Mild Mangal Dosha has limited effect, but it is prudent to factor it in during match making. Study the partner's chart alongside it."


def mangalRemediesList(loc: Any, status: Any) -> Any:
    m: Any = js.nullish(
        (_v3 if js.defined(_v3 := js.get(REMEDIES, pickLocale(loc))) else js.get(REMEDIES, "en")),
        {},
    )
    return js.nullish(
        (
            _v5
            if js.defined(_v5 := (_v4 if js.defined(_v4 := own(m, status)) else js.get(m, "mild")))
            else js.get_optional(js.get(REMEDIES, "en"), "mild")
        ),
        [],
    )


