def renderMangalDoshaHtml(data: Any, branding: Any = js.UNDEF) -> Any:
    data = withoutNullItems({**data, "Locale": safeLocale(js.get(data, "Locale"))})
    loc: Any = js.nullish(js.get(data, "Locale"), "")
    b: Any = resolveBranding(js.get(data, "Branding"), branding)
    subject: Any = js.nullish(js.get(data, "Subject"), {})
    mars: Any = js.nullish(js.get(data, "MarsPlacement"), {})
    title: Any = label(loc, "title_mangal")
    cover: Any = (
        ('<section class="cover">\n  ')
        + js.s(coverBrandingHtml(b))
        + ("\n  <h1>")
        + esc(title)
        + ('</h1>\n  <div class="subject">')
        + esc(js.get(subject, "name"))
        + ('</div>\n  <div class="meta">\n    ')
        + esc(label(loc, "born"))
        + " "
        + esc(js.get(subject, "birth_date"))
        + " "
        + esc(label(loc, "at"))
        + " "
        + esc(js.get(subject, "birth_time"))
        + ("<br>\n    ")
        + esc(js.get(subject, "birth_place"))
        + ("<br>\n    ")
        + esc(label(loc, "ascendant"))
        + ": "
        + esc(js.get(subject, "ascendant_sign"))
        + ('\n  </div>\n  <div class="status-badge ')
        + esc(badgeClass(data))
        + '">'
        + esc(statusBadgeText(loc, data))
        + ('</div>\n  <div class="generated">')
        + esc(label(loc, "generated"))
        + " "
        + esc(formatGenerated(js.get(data, "GeneratedAt")))
        + ("</div>\n</section>")
    )
    housesText: Any = formatHouses(loc, js.get(data, "HousesOccupied"))
    housesRow: Any = (
        (
            "<dt>"
            + esc(label(loc, "mars_houses"))
            + ("</dt>\n    <dd>")
            + esc(housesText)
            + ("</dd>\n    ")
        )
        if js.truthy(housesText)
        else ""
    )
    diagnostic: Any = (
        "<h2>"
        + esc(label(loc, "section_diagnostic"))
        + ('</h2>\n<div class="diagnostic">\n  <dl>\n    <dt>')
        + esc(label(loc, "mars_sign"))
        + ("</dt>\n    <dd>")
        + esc(js.get(mars, "sign"))
        + " ("
        + esc(js.get(mars, "dms_within"))
        + (")</dd>\n    <dt>")
        + esc(label(loc, "mars_nakshatra"))
        + ("</dt>\n    <dd>")
        + esc(js.get(mars, "nakshatra"))
        + ", "
        + esc(label(loc, "pada"))
        + " "
        + esc(js.get(mars, "pada"))
        + ("</dd>\n    ")
        + js.s(housesRow)
        + "<dt>"
        + esc(label(loc, "diagnosis"))
        + ("</dt>\n    <dd>")
        + esc(diagnosisText(loc, data))
        + ("</dd>\n  </dl>\n</div>")
    )
    cancellation: Any = ""
    if js.truthy(js.get(data, "Cancelled")):
        reasons: Any = (
            js.get(data, "CancelReasons") if js.is_array(js.get(data, "CancelReasons")) else []
        )
        cancellation = (
            "<h2>"
            + esc(label(loc, "section_cancellation"))
            + ('</h2>\n<div class="cancellation">\n  <p>')
            + esc(label(loc, "cancellation_intro"))
            + ("</p>\n  <ul>\n    ")
            + js.join(js.map_(reasons, (lambda r: "<li>" + esc(r) + "</li>")), ("\n    "))
            + ("\n  </ul>\n</div>")
        )
    marriage: Any = (
        "<h2>"
        + esc(label(loc, "section_marriage"))
        + ("</h2>\n<p>")
        + esc(marriageImplicationsText(loc, data))
        + "</p>"
    )
    remedies: Any = (
        "<h2>"
        + esc(label(loc, "section_remedies"))
        + ('</h2>\n<div class="remedies">\n  <p>')
        + esc(label(loc, "remedies_intro"))
        + ("</p>\n  <ul>\n    ")
        + js.join(
            js.map_(
                mangalRemediesList(loc, js.get(data, "Status")),
                (lambda r: "<li>" + esc(r) + "</li>"),
            ),
            ("\n    "),
        )
        + ("\n  </ul>\n</div>")
    )
    bodyHtml: Any = js.join(
        js.filter_([cover, diagnostic, cancellation, marriage, remedies], (lambda s: s != "")),
        ("\n\n"),
    )
    return layoutDocument(
        {
            "lang": js.or_(loc, "en"),
            "title": title,
            "branding": b,
            "bodyHtml": bodyHtml,
            "extraCss": EXTRA_CSS,
        }
    )
